css:
    * {
      padding: 0;
      margin: 0;
      box-sizing: border-box;
    }

    .container {
      width: 100vw;
      height: 100vh;
      background-color: rgb(8, 8, 32);
      position: relative;
      overflow: hidden;
    }

    .bub {
      --size: 130px;
      --left: 10%;
      --duration: 2s;
      --delay: 1s;
      width: var(--size);
      height: var(--size);
      border: 1px solid white;
      box-shadow: inset 5px -5px 10px white;
      border-radius: 50%;
      background-color: rgba(255, 255, 255, 0.1);
      position: absolute;
      bottom: -100px;
      left: var(--left);
      animation: bubble var(--duration) ease-in var(--delay) infinite;
      will-change: transform, opacity;
    }

    .bub::before {
      content: "";
      position: absolute;
      background-color: white;
      width: 15%;
      height: 15%;
      border-radius: 50%;
      top: 20%;
      right: 18%;
      box-shadow: 0 0 20px white;
    }

    /* Define bubble variations */
    .bub:nth-child(1) {
      --left: 10%;
      --duration: 2s;
      --delay: 1s;
    }

    .bub:nth-child(2) {
      --left: 20%;
      --duration: 1.5s;
      --delay: 1.4s;
    }

    .bub:nth-child(3) {
      --left: 28%;
      --duration: 5s;
      --delay: 3.8s;
    }

    .bub:nth-child(4) {
      --left: 40%;
      --duration: 1.8s;
      --delay: 0.5s;
    }

    .bub:nth-child(5) {
      --left: 75%;
      --duration: 2.3s;
      --delay: 2.5s;
    }

    .bub:nth-child(6) {
      --left: 90%;
      --duration: 2.5s;
      --delay: 3s;
    }

    .bub:nth-child(7) {
      --left: 60%;
      --duration: 2.2s;
      --delay: 2s;
    }

    .bub:nth-child(8) {
      --left: 50%;
      --duration: 1.6s;
      --delay: 2s;
    }

    .bub:nth-child(9) {
      --left: 65%;
      --duration: 1.8s;
      --delay: 2.1s;
    }

    .bub:nth-child(10) {
      --left: 3%;
      --duration: 2s;
      --delay: 1.5s;
    }

    @keyframes bubble {
      0% {
        opacity: 0;
        transform: translate(0, 0);
      }

      10% {
        opacity: 1;
      }

      95% {
        opacity: 1;
      }

      100% {
        transform: translate(90px, -70vh);
        opacity: 0;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      .bub {
        animation: none;
        opacity: 1;
        transform: none;
      }
    }
